// This file is getting too complex and will eventually need some refactoring

import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
    static targets = [
        "map",
        "gradeRadioButton",
        "gradeMin",
        "gradeMax",
        "customGradePicker",
        "filterCounter",
        "filterIcon",
    ]
    static values = {
        token: String,
        bounds: Object,
        problem: Object,
        locale: { type: String, default: "en" },
        draft: { type: Boolean, default: false },
        contribute: { type: Boolean, default: false },
        contributeSource: String,
    }

    connect() {
        mapboxgl.accessToken = this.tokenValue

        this.map = new mapboxgl.Map({
            container: "map",
            language: this.localeValue, // doesn't seem to work?
            locale: this.localeValue == "de" ? this.getDeLocale() : null,
            hash: true,
            style: `mapbox://styles/dgtlntv/cmi0wnif6004t01r0araj0ts0${
                this.draftValue ? "/draft" : ""
            }`,
            bounds: [
                [9.430320338084726, 46.28576190178245],  // Southwest corner
                [17.230613306834925, 49.18126637161225], // Northeast corner
            ],
            padding: 5,
        })

        this.addControls()

        this.map.on("load", () => {
            this.addLayers()
            this.centerMap()
            this.cleanHistory()
        })

        this.popup = null
        this.map.on("moveend", () => {
            if (this.popup != null) {
                this.popup.addTo(this.map)
                this.popup = null
            }
        })

        this.setupClickEvents()

        // FIXME: make this DRY (see Problem::GRADE_VALUES)
        this.allGrades = [
            "1a",
            "1a/+",
            "1a+",
            "1b",
            "1b/+",
            "1b+",
            "1c",
            "1c/+",
            "1c+",
            "2a",
            "2a/+",
            "2a+",
            "2b",
            "2b/+",
            "2b+",
            "2c",
            "2c/+",
            "2c+",
            "3a",
            "3a/+",
            "3a+",
            "3b",
            "3b/+",
            "3b+",
            "3c",
            "3c/+",
            "3c+",
            "4a",
            "4a/+",
            "4a+",
            "4b",
            "4b/+",
            "4b+",
            "4c",
            "4c/+",
            "4c+",
            "5a",
            "5a/+",
            "5a+",
            "5b",
            "5b/+",
            "5b+",
            "5c",
            "5c/+",
            "5c+",
            "6a",
            "6a/+",
            "6a+",
            "6b",
            "6b/+",
            "6b+",
            "6c",
            "6c/+",
            "6c+",
            "7a",
            "7a/+",
            "7a+",
            "7b",
            "7b/+",
            "7b+",
            "7c",
            "7c/+",
            "7c+",
            "8a",
            "8a/+",
            "8a+",
            "8b",
            "8b/+",
            "8b+",
            "8c",
            "8c/+",
            "8c+",
            "9a",
            "9a/+",
            "9a+",
            "9b",
            "9b/+",
            "9b+",
            "9c",
            "9c/+",
            "9c+",
        ]
    }

    addControls() {
        this.map.addControl(
            new mapboxgl.ScaleControl({
                maxWidth: 100,
                unit: "metric",
            })
        )

        this.map.addControl(new mapboxgl.NavigationControl())

        this.map.addControl(
            new mapboxgl.GeolocateControl({
                positionOptions: {
                    enableHighAccuracy: true,
                },
                trackUserLocation: true,
                showUserHeading: true,
            })
        )
    }

    addLayers() {
        this.map.addSource("problems", {
            type: "vector",
            url: "mapbox://dgtlntv.95ifk802",
            promoteId: "id",
        })

        this.map.addLayer(
            {
                id: "problems",
                type: "circle",
                source: "problems",
                "source-layer": "problems_8-85f5eq",
                minzoom: 15,
                layout: {
                    visibility: "visible",
                },
                paint: {
                    "circle-radius": [
                        "interpolate",
                        ["linear"],
                        ["zoom"],
                        15,
                        2,
                        18,
                        4,
                        22,
                        10,
                    ],
                    "circle-color": "#878A8D",
                    "circle-opacity": [
                        "interpolate",
                        ["linear"],
                        ["zoom"],
                        14.5,
                        0,
                        15,
                        1,
                    ],
                },
                filter: ["match", ["geometry-type"], ["Point"], true, false],
            },
            "areas" // layer will be inserted just before this layer
        )

        // CONTRIBUTE LAYERS

        if (this.contributeValue) {
            this.map.addSource("contribute", {
                type: "geojson",
                data: this.contributeSourceValue,
            })

            this.map.addLayer(
                {
                    id: "contribute-problems",
                    type: "circle",
                    source: "contribute",
                    // 'source-layer': 'problems-ayes3a',
                    // 'minzoom': 12,
                    layout: {
                        visibility: "visible",
                    },
                    paint: {
                        "circle-radius": [
                            "interpolate",
                            ["linear"],
                            ["zoom"],
                            12,
                            6,
                            17,
                            20,
                            18,
                            25,
                            19,
                            50,
                            20,
                            50,
                            21,
                            50,
                            22,
                            20,
                        ],
                        "circle-color": "#FFCC02",
                        "circle-opacity": 0.25,
                        "circle-stroke-width": 2,
                        "circle-stroke-color": "white",
                    },
                    filter: [
                        "match",
                        ["geometry-type"],
                        ["Point"],
                        true,
                        false,
                    ],
                },
                "areas" // layer will be inserted just before this layer
            )

            this.map.addLayer({
                id: "contribute-problems-texts",
                type: "symbol",
                source: "contribute",
                // 'source-layer': 'problems-ayes3a',
                minzoom: 16,
                layout: {
                    visibility: "visible",
                    "text-allow-overlap": true,
                    "text-field": ["to-string", ["get", "name"]],
                    "text-size": [
                        "interpolate",
                        ["linear"],
                        ["zoom"],
                        19,
                        10,
                        22,
                        20,
                    ],
                },
                paint: {
                    "text-color": "#333",
                    "text-halo-color": "hsl(0, 0%, 100%)",
                    "text-halo-width": 1,
                },
                filter: ["match", ["geometry-type"], ["Point"], true, false],
            })
        }
    }

    centerMap() {
        if (this.hasBoundsValue) {
            let bounds = this.boundsValue

            this.flyToBounds([
                [bounds.southWestLon, bounds.southWestLat],
                [bounds.northEastLon, bounds.northEastLat],
            ])
        }

        if (this.hasProblemValue) {
            let problem = this.problemValue

            this.map.flyTo({
                center: [problem.lon, problem.lat],
                zoom: 20,
                speed: 2,
            })

            if (!this.contributeValue) {
                // FIXME: make it DRY
                const coordinates = [problem.lon, problem.lat]
                var name = problem.name
                if (this.localeValue == "en" && problem.nameEn) {
                    name = problem.nameEn
                }
                const html = `<a href="/${
                    this.localeValue
                }/redirects/new?problem_id=${problem.id}" target="_blank">${
                    name || ""
                }</a><span class="text-gray-400 ml-1">${problem.grade}</span>`

                // will be displayed thanks to the 'moveend' event code above
                this.popup = new mapboxgl.Popup({
                    closeButton: false,
                    focusAfterOpen: false,
                    offset: [0, -8],
                })
                    .setLngLat(coordinates)
                    .setHTML(html)
            }
        }
    }

    cleanHistory() {
        this.map.on("movestart", () => {
            // we remove the arguments (like area_id or problem_id) because mapbox provides a hash (url fragment) to allow for friendly url sharing
            // TODO: replace url only when user does something (eg. moves, closes a modal)

            var url = ""
            if (this.contributeValue) {
                url = `/${this.localeValue}/mapping/map`
            } else {
                url = `/${this.localeValue}/map`
            }

            history.replaceState({}, "", url)
        })
    }

    setupClickEvents() {
        this.map.on("mouseenter", "problems", () => {
                this.map.getCanvas().style.cursor = "pointer"
            })
            this.map.on("mouseleave", "problems", () => {
                this.map.getCanvas().style.cursor = ""
            })

            this.map.on("click", "problems", (e) => {
                let problem = e.features[0].properties

                // FIXME: make it DRY
                const coordinates = e.features[0].geometry.coordinates.slice()
                var name = problem.name
                if (this.localeValue == "en" && problem.nameEn) {
                    name = problem.nameEn
                }
                const html = `<a href="/${
                    this.localeValue
                }/redirects/new?problem_id=${problem.id})" target="_blank">${
                    name || ""
                }</a><span class="text-gray-400 ml-1">${problem.grade}</span>`

                new mapboxgl.Popup({
                    closeButton: false,
                    focusAfterOpen: false,
                    offset: [0, -8],
                })
                    .setLngLat(coordinates)
                    .setHTML(html)
                    .addTo(this.map)
            })

        this.map.on(
            "mouseenter",
            ["contribute-problems", "contribute-problems-texts"],
            () => {
                this.map.getCanvas().style.cursor = "pointer"
            }
        )
        this.map.on(
            "mouseleave",
            ["contribute-problems", "contribute-problems-texts"],
            () => {
                this.map.getCanvas().style.cursor = ""
            }
        )

        // FIXME: make DRY
        this.map.on(
            "click",
            ["contribute-problems", "contribute-problems-texts"],
            (e) => {
                let group = e.features[0].properties

                // FIXME: make it DRY
                const coordinates = e.features[0].geometry.coordinates.slice()
                var name = group.name
                if (this.localeValue == "en" && group.nameEn) {
                    name = group.nameEn
                }

                let problems = JSON.parse(group.problems)
                const html = problems
                    .map(
                        (problem) => `<div>
        <a href="/${this.localeValue}/mapping/problems/${
                            problem.id
                        }" target="_blank">${problem.name || ""}</a>
        <span class="text-gray-400 ml-1">${problem.grade}</span>
        <span class="text-gray-400 ml-1 font-semibold">(${
            problem.ascents
        })</span>
        </div>`
                    )
                    .join("")

                new mapboxgl.Popup({
                    closeButton: false,
                    focusAfterOpen: false,
                    offset: [0, -8],
                })
                    .setLngLat(coordinates)
                    .setHTML(html)
                    .addTo(this.map)
            }
        )

        // FIXME: make DRY
        this.map.on("mouseenter", "pois", () => {
            if (this.map.getZoom() >= 12) {
                this.map.getCanvas().style.cursor = "pointer"
            }
        })
        this.map.on("mouseleave", "pois", () => {
            if (this.map.getZoom() >= 12) {
                this.map.getCanvas().style.cursor = ""
            }
        })

        this.map.on("click", "pois", (e) => {
            if (this.map.getZoom() >= 12) {
                // FIXME: make it DRY
                const coordinates = e.features[0].geometry.coordinates.slice()
                const html = `<a href="${
                    e.features[0].properties.googleUrl
                }" target="_blank">${
                    this.localeValue == "de"
                        ? "Auf Google ansehen"
                        : "See on Google"
                }</a>`

                new mapboxgl.Popup({
                    closeButton: false,
                    focusAfterOpen: false,
                    offset: [0, -8],
                })
                    .setLngLat(coordinates)
                    .setHTML(html)
                    .addTo(this.map)
            }
        })

        // FIXME: make DRY
        this.map.on("mouseenter", "areas", () => {
            if (this.map.getZoom() < 15) {
                this.map.getCanvas().style.cursor = "pointer"
            }
        })
        this.map.on("mouseleave", "areas", () => {
            if (this.map.getZoom() < 15) {
                this.map.getCanvas().style.cursor = ""
            }
        })

        this.map.on("click", "areas", (e) => {
            if (this.map.getZoom() < 15) {
                let props = e.features[0].properties
                this.flyToBounds([
                    [props.southWestLon, props.southWestLat],
                    [props.northEastLon, props.northEastLat],
                ])
            }
        })

        // FIXME: make DRY
        this.map.on("mouseenter", "areas-hulls", () => {
            if (this.map.getZoom() < 15) {
                this.map.getCanvas().style.cursor = "pointer"
            }
        })
        this.map.on("mouseleave", "areas-hulls", () => {
            if (this.map.getZoom() < 15) {
                this.map.getCanvas().style.cursor = ""
            }
        })

        this.map.on("click", "areas-hulls", (e) => {
            if (this.map.getZoom() < 15) {
                let props = e.features[0].properties
                // console.log(props)
                this.flyToBounds([
                    [props.southWestLon, props.southWestLat],
                    [props.northEastLon, props.northEastLat],
                ])
            }
        })

        // FIXME: make DRY
        this.map.on("mouseenter", "regions", () => {
            if (this.map.getZoom() <= 10) {
                this.map.getCanvas().style.cursor = "pointer"
            }
        })
        this.map.on("mouseleave", "regions", () => {
            if (this.map.getZoom() <= 10) {
                this.map.getCanvas().style.cursor = ""
            }
        })

        this.map.on("click", "regions", (e) => {
            if (this.map.getZoom() <= 10) {
                let props = e.features[0].properties
                this.flyToBounds([
                    [props.southWestLon, props.southWestLat],
                    [props.northEastLon, props.northEastLat],
                ])
            }
        })

        this.map.on("mouseenter", "clusters", () => {
            if (this.map.getZoom() <= 12) {
                this.map.getCanvas().style.cursor = "pointer"
            }
        })
        this.map.on("mouseleave", "clusters", () => {
            if (this.map.getZoom() <= 12) {
                this.map.getCanvas().style.cursor = ""
            }
        })

        this.map.on("click", "clusters", (e) => {
            if (this.map.getZoom() <= 12) {
                let props = e.features[0].properties
                this.flyToBounds([
                    [props.southWestLon, props.southWestLat],
                    [props.northEastLon, props.northEastLat],
                ])
            }
        })
    }

    flyToBounds(bounds) {
        var cameraOptions = this.map.cameraForBounds(bounds, {
            padding: { top: 20, bottom: 100, left: 20, right: 20 },
        })

        cameraOptions.zoom = Math.max(15, cameraOptions.zoom)
        cameraOptions.speed = 2

        this.map.flyTo(cameraOptions)
    }

    // https://github.com/mapbox/mapbox-gl-js/blob/20e8fd2b60fb751f5846d3be2d46dfa76d940324/src/ui/default_locale.js
    getDeLocale() {
        return {
            "AttributionControl.ToggleAttribution":
                "Attribution umschalten",
            "AttributionControl.MapFeedback": "Karten-Feedback",
            "FullscreenControl.Enter": "Vollbildmodus",
            "FullscreenControl.Exit": "Vollbildmodus verlassen",
            "GeolocateControl.FindMyLocation": "Meinen Standort finden",
            "GeolocateControl.LocationNotAvailable":
                "Standort nicht verfügbar",
            "LogoControl.Title": "Mapbox Logo",
            "Map.Title": "Karte",
            "NavigationControl.ResetBearing": "Nach Norden ausrichten",
            "NavigationControl.ZoomIn": "Vergrößern",
            "NavigationControl.ZoomOut": "Verkleinern",
            "ScrollZoomBlocker.CtrlMessage":
                "Verwenden Sie Strg + Scrollen zum Zoomen",
            "ScrollZoomBlocker.CmdMessage":
                "Verwenden Sie ⌘ + Scrollen zum Zoomen",
            "TouchPanBlocker.Message":
                "Verwenden Sie zwei Finger, um die Karte zu bewegen",
        }
    }

    // =========================================================
    // TODO: move the filters logic into its own controller
    // =========================================================

    didSelectFilter(event) {
        this.gradeRadioButton = event.target.value

        if (this.gradeRadioButton == "custom") {
            this.customGradePickerTarget.classList.remove("hidden")
        } else {
            this.customGradePickerTarget.classList.add("hidden")
        }
    }

    applyFilters() {
        this.filterCounterTarget.classList.remove("hidden")
        this.filterIconTarget.classList.add("hidden")

        var grades = []
        if (this.gradeRadioButton == "beginner") {
            grades = [
                "1a",
                "1a+",
                "1b",
                "1b+",
                "1c",
                "1c+",
                "2a",
                "2a+",
                "2b",
                "2b+",
                "2c",
                "2c+",
                "3a",
                "3a+",
                "3b",
                "3b+",
                "3c",
                "3c+",
            ]
        } else if (this.gradeRadioButton == "level4") {
            grades = ["4a", "4a+", "4b", "4b+", "4c", "4c+"]
        } else if (this.gradeRadioButton == "level5") {
            grades = ["5a", "5a+", "5b", "5b+", "5c", "5c+"]
        } else if (this.gradeRadioButton == "level6") {
            grades = ["6a", "6a+", "6b", "6b+", "6c", "6c+"]
        } else if (this.gradeRadioButton == "level7") {
            grades = ["7a", "7a+", "7b", "7b+", "7c", "7c+"]
        } else if (this.gradeRadioButton == "level8") {
            grades = ["8a", "8a+", "8b", "8b+", "8c", "8c+"]
        } else if (this.gradeRadioButton == "custom") {
            let gradeMin = this.gradeMinTarget.value
            let gradeMax = this.gradeMaxTarget.value
            grades = this.allGrades.slice(
                this.allGrades.indexOf(gradeMin),
                this.allGrades.indexOf(gradeMax) + 2
            )
        } else {
            grades = this.allGrades
        }

        this.applyLayerFilter("problems", grades)
        this.applyLayerFilter("problems-texts", grades)
    }

    clearFilters() {
        this.gradeRadioButton == null

        this.filterCounterTarget.classList.add("hidden")
        this.filterIconTarget.classList.remove("hidden")

        this.gradeRadioButtonTargets.forEach((item) => {
            item.checked = false
        })

        this.applyLayerFilter("problems", this.allGrades)
        this.applyLayerFilter("problems-texts", this.allGrades)
    }

    applyLayerFilter(layer, grades) {
        this.map.setFilter(layer, [
            "match",
            ["get", "grade"],
            grades,
            true,
            false,
        ])
    }

    didSelectGradeMin() {
        let indexMin = this.allGrades.indexOf(this.gradeMinTarget.value)
        let indexMax = this.allGrades.indexOf(this.gradeMaxTarget.value)
        this.gradeMaxTarget.value = this.allGrades[Math.max(indexMin, indexMax)]
    }

    didSelectGradeMax() {
        let indexMin = this.allGrades.indexOf(this.gradeMinTarget.value)
        let indexMax = this.allGrades.indexOf(this.gradeMaxTarget.value)
        this.gradeMinTarget.value = this.allGrades[Math.min(indexMin, indexMax)]
    }

    // =========================================================

    // =========================================================
    // Hooks coming from search_controller
    // =========================================================

    gotoproblem(event) {
        this.map.flyTo({
            center: [event.detail.lon, event.detail.lat],
            zoom: 20,
            speed: 2,
        })

        // FIXME: make it DRY
        const coordinates = [event.detail.lon, event.detail.lat]
        const html = `<a href="/${this.localeValue}/redirects/new?problem_id=${
            event.detail.id
        }" target="_blank">${
            event.detail.name || ""
        }</a><span class="text-gray-400 ml-1">${event.detail.grade}</span>`

        new mapboxgl.Popup({
            closeButton: false,
            focusAfterOpen: false,
            offset: [0, -8],
        })
            .setLngLat(coordinates)
            .setHTML(html)
            .addTo(this.map)
    }

    gotoarea(event) {
        this.flyToBounds([
            [event.detail.south_west_lon, event.detail.south_west_lat],
            [event.detail.north_east_lon, event.detail.north_east_lat],
        ])
    }
}

class MapController < ApplicationController
  layout "map"

  def index
    if params[:slug] && (area = Area.find_by(slug: params[:slug]))
      @area = area # FIXME: don't forget to refactor _map_nav when changing this
      @bounds = {
        south_west_lat: area.bounds[:south_west].lat,
        south_west_lon: area.bounds[:south_west].lon,
        north_east_lat: area.bounds[:north_east].lat,
        north_east_lon: area.bounds[:north_east].lon
      }.
      with_indifferent_access.deep_transform_keys { |key| key.camelize(:lower) }
    end

    if params[:pid] && (problem = Problem.find(params[:pid]))
      location = if params[:contribute]
        problem.contribution_requests.first&.location_estimated
      else
        problem.location
      end

      return unless location.present?

      @problem = {
        id: problem.id, # FIXME: don't forget to refactor _map_nav when changing this
        lat: location.lat,
        lon: location.lon,
        name: I18n.with_locale(:de) { problem.name_with_fallback },
        name_en: I18n.with_locale(:en) { problem.name_with_fallback },
        grade: problem.grade
      }.
      with_indifferent_access.deep_transform_keys { |key| key.camelize(:lower) }
    end
  end
end

